630	static void andes_cpu_lm_init(Object *obj)
631	{
632	    CPURISCVState *env = &RISCV_CPU(obj)->env;
633	    CPUState *cs = CPU(obj);
634	
635	    /* get soc lm properties, if not set, disable the local memory support */
636	    uint64_t isize, dsize;
637	    SOC_PROP_SET_DEF_IF_NOT_SET(ilm_default_enable, env->ilm_default_enable, bool, false)
638	    SOC_PROP_SET_DEF_IF_NOT_SET(dlm_default_enable, env->dlm_default_enable, bool, false)
639	    SOC_PROP_SET_DEF_IF_NOT_SET(ilm_base, env->ilm_base, uint64, 0x0)
640	    SOC_PROP_SET_DEF_IF_NOT_SET(ilm_size, isize, uint64, 0x0)
641	    SOC_PROP_SET_DEF_IF_NOT_SET(dlm_base, env->dlm_base, uint64, 0x0)
642	    SOC_PROP_SET_DEF_IF_NOT_SET(dlm_size, dsize, uint64, 0x0)
643	    env->ilm_size = isize & (uint32_t)-1;
644	    env->dlm_size = dsize & (uint32_t)-1;
645	
646	    env->cpu_as_root = g_new(MemoryRegion, 1);
647	    env->cpu_as_mem = g_new(MemoryRegion, 1);
648	
649	    /* Outer container... */
650	    memory_region_init(env->cpu_as_root, OBJECT(obj), "cpu-as-root", ~0ull);
651	    memory_region_set_enabled(env->cpu_as_root, true);
652	
653	    memory_region_init_alias(env->cpu_as_mem, OBJECT(obj), "cpu-as-mem",
654	                             get_system_memory(), 0, ~0ull);
655	    memory_region_add_subregion_overlap(env->cpu_as_root, 0,
656	                                        env->cpu_as_mem, 0);
657	    memory_region_set_enabled(env->cpu_as_mem, true);
658	
659	    cs->num_ases = 1;
660	    cpu_address_space_init(cs, 0, "cpu-memory", env->cpu_as_root);
661	    env->mask_ilm = isize? g_new(MemoryRegion, 1) : NULL;
662	    env->mask_dlm = dsize? g_new(MemoryRegion, 1) : NULL;
663	}
