665	static void andes_cpu_lm_realize(DeviceState *dev)
666	{
667	    CPURISCVState *env = &RISCV_CPU(dev)->env;
668	    int lm_num = env->mhartid;
669	
670	    if (env->mask_ilm) {
671	        g_autofree char *ilm_name =
672	            g_strdup_printf("%s%d", "riscv.andes.ae350.ilm", lm_num);
673	        memory_region_init_ram(env->mask_ilm, OBJECT(dev), ilm_name,
674	                               env->ilm_size, &error_fatal);
675	        /* local memory operation */
676	        env->mask_ilm->ops = &local_mem_ops;
677	        env->mask_ilm->opaque = env->mask_ilm;
678	
