1360	static int andesim_newlib_open_flags(uint64_t nl)
1361	{
1362	    int flags = 0;
1363	    switch (nl & 3) {
1364	    case 0: flags |= O_RDONLY; break;
1365	    case 1: flags |= O_WRONLY; break;
1366	    case 2: flags |= O_RDWR;   break;
1367	    }
1368	    if (nl & 0x0008) { flags |= O_APPEND;   }
1369	    if (nl & 0x0200) { flags |= O_CREAT;    }
1370	    if (nl & 0x0400) { flags |= O_TRUNC;    }
1371	    if (nl & 0x0800) { flags |= O_EXCL;     }
1372	    if (nl & 0x4000) { flags |= O_NONBLOCK; }
1373	    if (nl & 0x8000) { flags |= O_NOCTTY;   }
1374	    return flags;
