#define ANDESIM_HTIF_PUTCHAR_OFFSET  0x4
#define ANDESIM_HTIF_CMD_OFFSET      0x10
#define ANDESIM_HTIF_CMD_HIGH_OFFSET 0x14
#define ANDESIM_MAGIC_MEM_WORDS      8

/*
 * Newlib's <sys/_default_fcntl.h> uses BSD-derived O_* values that differ
 * from the Linux ABI (O_CREAT=0x200 vs 0x40, O_TRUNC=0x400 vs 0x200, ...).
 * Pass-through would drop O_CREAT, so a fopen("w") of a new file fails
 * with ENOENT. Translate flag-by-flag (same table as the vsim device).
 */
static int andesim_newlib_open_flags(uint64_t nl)
{
    int flags = 0;
    switch (nl & 3) {
    case 0: flags |= O_RDONLY; break;
    case 1: flags |= O_WRONLY; break;
    case 2: flags |= O_RDWR;   break;
    }
    if (nl & 0x0008) { flags |= O_APPEND;   }
    if (nl & 0x0200) { flags |= O_CREAT;    }
    if (nl & 0x0400) { flags |= O_TRUNC;    }
    if (nl & 0x0800) { flags |= O_EXCL;     }
    if (nl & 0x4000) { flags |= O_NONBLOCK; }
    if (nl & 0x8000) { flags |= O_NOCTTY;   }
    return flags;
}

/* NUL-terminated string from guest RAM (paths); caller g_free()s. */
static char *andesim_strdup_guest(uint64_t gpa)
{
    GString *s = g_string_new(NULL);
    char c;

    do {
        cpu_physical_memory_read(gpa + s->len, &c, 1);
        if (c) {
            g_string_append_c(s, c);
        }
    } while (c && s->len < PATH_MAX);
    return g_string_free(s, false);
}

/*
 * Store the two fields the guest-side newlib stat consumers read back
 * into the guest's struct stat: st_mode (u32 at offset 4) and st_size
 * (u64 at offset 16) -- the same two fields, at the same offsets, that
 * the vsim device writes through its pico_stat view.
 */
static void andesim_store_guest_stat(uint64_t gpa, const struct stat *st)
{
    uint8_t b[8];

    stl_le_p(b, (uint32_t)st->st_mode);
    cpu_physical_memory_write(gpa + 4, b, 4);
    stq_le_p(b, (uint64_t)st->st_size);
    cpu_physical_memory_write(gpa + 16, b, 8);
}

/*
 * The HTIF syscall table. Numbers and semantics mirror the vsim device's
 * sim_syscall_table exactly; failures return -1 (full-width, like the
 * host calls' sign-extended returns). Buffers bounce through the host
 * heap; guest pointers are guest-physical (the vplat runtime runs
 * bare-metal M-mode, VA == PA).
 */
static uint64_t andesim_htif_syscall(const uint64_t *m)
{
    const uint64_t a0 = m[1], a1 = m[2], a2 = m[3], a3 = m[4];

    switch (m[0]) {
    case 5: /* gettimeofday */
    {
        struct timeval tv;
        uint8_t b[16];

        if (gettimeofday(&tv, NULL) != 0) {
            return (uint64_t)-1;
        }
#if defined(TARGET_RISCV32)
        stl_le_p(b, (uint32_t)tv.tv_sec);
        stl_le_p(b + 4, (uint32_t)tv.tv_usec);
        cpu_physical_memory_write(a0, b, 8);
#else
        stq_le_p(b, (uint64_t)tv.tv_sec);
        stq_le_p(b + 8, (uint64_t)tv.tv_usec);
        cpu_physical_memory_write(a0, b, 16);
#endif
        return 0;
    }
    case 6: /* open */
    {
        char *path = andesim_strdup_guest(a0);
        int fd = open(path, andesim_newlib_open_flags(a1), (mode_t)a2);

        if (fd < 0) {
            qemu_log_mask(LOG_GUEST_ERROR,
                          "andes_ae350: htif open('%s', %#" PRIx64 ") failed: %s\n",
                          path, a1, strerror(errno));
        }
        g_free(path);
        return fd;
    }
    case 7: /* write */
    {
        void *buf = g_malloc(a2);
        ssize_t r;

        cpu_physical_memory_read(a1, buf, a2);
        r = write((int)a0, buf, a2);
        g_free(buf);
        return r;
    }
    case 8: /* getcwd */
    {
        char *buf = g_malloc0(a1);
        char *r = getcwd(buf, a1);

        if (r) {
            cpu_physical_memory_write(a0, buf, a1);
        }
        g_free(buf);
        return r ? a0 : 0;
    }
    case 9: /* lseek */
        return lseek((int)a0, (off_t)a1, (int)a2);
    case 10: /* read */
    {
        void *buf = g_malloc(a2);
        ssize_t r = read((int)a0, buf, a2);

        if (r > 0) {
            cpu_physical_memory_write(a1, buf, r);
        }
        g_free(buf);
        return r;
    }
    case 11: /* flen */
    {
        struct stat st;

        if (fstat((int)a0, &st) != 0) {
            return (uint64_t)-1;
        }
        return st.st_size;
    }
    case 12: /* close */
        return close((int)a0);
    case 13: /* access */
    {
        char *path = andesim_strdup_guest(a0);
        int r = access(path, (int)a1);

        g_free(path);
        return r;
    }
    case 14: /* faccessat */
    {
        char *path = andesim_strdup_guest(a1);
        int r = faccessat((int)a0, path, (int)a2, (int)a3);

        g_free(path);
        return r;
    }
    case 15: /* fstat */
    {
        struct stat st;
        int r = fstat((int)a0, &st);

        if (r == 0) {
            andesim_store_guest_stat(a1, &st);
        }
        return r;
    }
