{
    Object *soc = object_resolve_path("/machine/soc", NULL);
    if (soc == NULL) {
        return NULL;
    }

    Error *err = NULL;
    QObject *prop_qobj = object_property_get_qobject(soc, name, &err);
    return prop_qobj;
}

